with w as(select * from public.works where id in(1392,3263,2401,1479,3385,3224,5737,5832,3503,1375,4980,6004,6006,6044,1512)),e as(select * from public.editions where work_id in(select id from w) or isbn_13=any(array['9789060571552','9789049205430','9789025467418','9789060574225','9789022986790','9789022539323','9789024556595','9789044508772','9789022996621','9789025305567','9789044502985','9789022531259','9789029575379','9789027466976','9789000398034']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','qvplwejffhjvxaypmjut','works',(select coalesce(jsonb_agg(to_jsonb(x)order by id),'[]')from w x),'authors',(select coalesce(jsonb_agg(to_jsonb(x)order by id),'[]')from public.authors x where id in(select author_id from w)),'editions',(select coalesce(jsonb_agg(to_jsonb(x)order by id),'[]')from e x),'metadata',(select coalesce(jsonb_agg(to_jsonb(x)order by edition_id),'[]')from public.catalog_edition_metadata x where work_id in(select id from w)),'descriptions',(select coalesce(jsonb_agg(to_jsonb(x)order by work_id,language),'[]')from public.catalog_work_descriptions x where work_id in(select id from w)and language='nl'))as preflight;
